selector_to_html = {"a[href=\"#pyskyfire-thermo-eos-coolpropeos\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo.eos.CoolPropEOS<a class=\"headerlink\" href=\"#pyskyfire-thermo-eos-coolpropeos\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.state_pT\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.state_pT\">\n<span class=\"sig-name descname\"><span class=\"pre\">state_pT</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state at pressure <code class=\"docutils literal notranslate\"><span class=\"pre\">p</span></code> and temperature <code class=\"docutils literal notranslate\"><span class=\"pre\">T</span></code>.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.state_ph\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.state_ph\">\n<span class=\"sig-name descname\"><span class=\"pre\">state_ph</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state at pressure <code class=\"docutils literal notranslate\"><span class=\"pre\">p</span></code> and specific enthalpy <code class=\"docutils literal notranslate\"><span class=\"pre\">h</span></code>.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.resolver\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.resolver\">\n<span class=\"sig-name descname\"><span class=\"pre\">resolver</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_ref</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../state/FluidStateResolver.html#pyskyfire.thermo.state.FluidStateResolver\" title=\"pyskyfire.thermo.state.FluidStateResolver\"><span class=\"pre\">FluidStateResolver</span></a></span></span></dt><dd><p>The state resolver, probed at the first pressure it is asked about.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.speed_of_sound\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.speed_of_sound\">\n<span class=\"sig-name descname\"><span class=\"pre\">speed_of_sound</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Single-phase speed of sound; NaN inside the dome, where it is not defined.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.entropy\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.entropy\">\n<span class=\"sig-name descname\"><span class=\"pre\">entropy</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Specific entropy of <code class=\"docutils literal notranslate\"><span class=\"pre\">state</span></code> [J kg\u207b\u00b9 K\u207b\u00b9].</p></dd>", "a[href=\"../fluid/Fluid.html#pyskyfire.thermo.fluid.Fluid\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.fluid.Fluid\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.fluid.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Fluid</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">type</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">propellants</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fractions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">basis</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'mass'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">precision</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">3</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Mixture helper for fluids.</p><p>Stores a set of component names and composition.</p><p class=\"rubric\">Notes</p><p>Fractions are re-normalized internally when converting to mole basis to\nguard against small rounding errors.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.isentropic\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.isentropic\">\n<span class=\"sig-name descname\"><span class=\"pre\">isentropic</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state reached from <code class=\"docutils literal notranslate\"><span class=\"pre\">state</span></code> by an isentropic process to <code class=\"docutils literal notranslate\"><span class=\"pre\">p</span></code>.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.state_hs\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.state_hs\">\n<span class=\"sig-name descname\"><span class=\"pre\">state_hs</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">s</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_guess</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1000000.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tolerance</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1e-10</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The state at <code class=\"docutils literal notranslate\"><span class=\"pre\">(h,</span> <span class=\"pre\">s)</span></code>.</p><p>CoolProp\u2019s own <code class=\"docutils literal notranslate\"><span class=\"pre\">(h,</span> <span class=\"pre\">s)</span></code> flash is used where it answers. It refuses\nstates beyond the equation\u2019s temperature range, though its <code class=\"docutils literal notranslate\"><span class=\"pre\">(p,</span> <span class=\"pre\">h)</span></code>\nflash still extrapolates there, so where it refuses the pressure is\nfound along the isenthalp instead. At constant enthalpy\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ds/dp</span> <span class=\"pre\">=</span> <span class=\"pre\">-1/(rho*T)</span></code>, and a Newton step in <code class=\"docutils literal notranslate\"><span class=\"pre\">ln</span> <span class=\"pre\">p</span></code> with that\nslope converges in a few steps from far off.</p></dd>", "a[href=\"../state/FluidStateResolver.html#pyskyfire.thermo.state.FluidStateResolver\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidStateResolver\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidStateResolver</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_ref</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Resolve fluid states from <code class=\"docutils literal notranslate\"><span class=\"pre\">(h,</span> <span class=\"pre\">p)</span></code>, with cached saturation data.</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.eos.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CoolPropEOS</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">EquationOfState</span></code></p><p>A real fluid, from CoolProp.</p><p class=\"rubric\">Notes</p><p>A <code class=\"docutils literal notranslate\"><span class=\"pre\">(p,</span> <span class=\"pre\">T)</span></code> pair lying on the saturation line doesn\u2019t identify a state:\nit could be liquid, vapour or anything between. <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.CoolPropEOS.state_pT\" title=\"pyskyfire.thermo.eos.CoolPropEOS.state_pT\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_pT()</span></code></a> reads\nsuch a pair as saturated liquid, a millikelvin into the liquid, because\na pump inlet drawn from a tank at its own vapour pressure is where this\ncomes up. Give the enthalpy through <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.CoolPropEOS.state_ph\" title=\"pyskyfire.thermo.eos.CoolPropEOS.state_ph\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_ph()</span></code></a> to mean anything\nelse.</p></dd>", "a[href=\"../transport/FluidTransport.html#pyskyfire.thermo.transport.FluidTransport\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.transport.FluidTransport\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.transport.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidTransport</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../fluid/Fluid.html#pyskyfire.thermo.fluid.Fluid\" title=\"pyskyfire.thermo.fluid.Fluid\"><span class=\"pre\">Fluid</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>CoolProp-backed transport/thermo properties for a single fluid.</p><p>Thin wrapper around <strong>CoolProp</strong> that exposes convenient getters using a\n<a class=\"reference internal\" href=\"../fluid/Fluid.html#pyskyfire.thermo.fluid.Fluid\" title=\"pyskyfire.thermo.fluid.Fluid\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Fluid</span></code></a> to obtain the CoolProp fluid string.</p><p class=\"rubric\">Notes</p></dd>", "a[href=\"#pyskyfire.thermo.eos.CoolPropEOS.__getstate__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.CoolPropEOS.__getstate__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__getstate__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../state/FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
